        idx=out.index("\n"+h2b+"\n")
    except ValueError:
        return "!!NOSPLIT "+repr(out)
    return out[:idx]
def probe(label,a):
    print("### %s"%label)
    print("  IN : %r"%a)
    print("  OUT: %r"%run(a))
PYEOF
